INSERT INTO qnas(id,member_id,product_id,type,title,content,is_private,deleted_at,created_at,updated_at) VALUES
(1,27,1668,'PRODUCT','사용법 문의','내추럴발란스 치킨 덴탈바 처음 사용하는데 세척 방법이 궁금해요.',false,NULL,'2023-11-22 22:42:47','2023-11-22 22:42:47'),
(2,28,NULL,'GENERAL','교환/환불 문의','상품을 받았는데 교환하고 싶어요. 절차가 어떻게 되나요?',false,NULL,'2023-11-23 10:08:20','2023-11-23 10:08:20'),
(3,21,NULL,'GENERAL','쿠폰 문의','신규 가입 쿠폰이 보이지 않아요.',false,NULL,'2023-11-24 13:02:15','2023-11-24 13:02:15'),
(4,35,NULL,'GENERAL','세일 기간 문의','이번 세일은 언제까지 진행되나요?',false,NULL,'2023-11-25 20:45:47','2023-11-25 20:45:47'),
